172	static bool sf32lb58_bt_rx_ring_valid(struct circular_buf *rx_ring)
173	{
174	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
175	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
176	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
177	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
178	  long buf_size = rx_ring->buffer_size;
179	
180	  return buf_size == (long)SF32LB58_BT_RING_DATA_SIZE &&
181	         rd_idx <= SF32LB58_BT_RING_DATA_SIZE &&
182	         wr_idx <= SF32LB58_BT_RING_DATA_SIZE;
183	}
184	
185	static bool sf32lb58_bt_rx_ring_ready(const char *tag)
186	{
187	  struct circular_buf *rx_ring =
188	      (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
189	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
190	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
191	  long buf_size = rx_ring->buffer_size;
192	
193	  if (!sf32lb58_bt_rx_ring_valid(rx_ring))
194	    {
195	      syslog(LOG_WARNING,
196	             "%s rx ring invalid: buf=%ld expected=%lu rd=%08lx wr=%08lx\n",
197	             tag,
198	             buf_size,
199	             (unsigned long)SF32LB58_BT_RING_DATA_SIZE,
200	             (unsigned long)rd_ptr,
201	             (unsigned long)wr_ptr);
202	      return false;
203	    }
204	
205	  return true;
206	}
