208	static int sf32lb58_bt_wait_rx_ring_ready(void)
209	{
210	  struct circular_buf *rx_ring =
211	      (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
212	  int i;
213	
214	  syslog(LOG_INFO, "sf32lb58 wait_rx_ring: buf=0x%08x size=%lu\n",
215	         (unsigned int)SF32LB58_BT_RX_BUF_ADDR,
216	         (unsigned long)SF32LB58_BT_RX_BUF_SIZE);
217	
218	  for (i = 0; i < 1000; i++)
219	    {
220	      up_invalidate_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
221	                           (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
222	                           SF32LB58_BT_RX_BUF_SIZE);
223	
224	      if (sf32lb58_bt_rx_ring_valid(rx_ring))
225	        {
226	          syslog(LOG_INFO, "sf32lb58 wait_rx_ring: ready after %d iters\n", i);
227	          return OK;
228	        }
229	
230	      if (i < 5 || i % 100 == 0)
231	        {
232	          syslog(LOG_INFO, "sf32lb58 wait_rx_ring: iter=%d "
233	                 "buf_size=%ld rd=%08lx wr=%08lx\n",
234	                 i,
235	                 rx_ring->buffer_size,
236	                 (unsigned long)rx_ring->read_idx_mirror,
237	                 (unsigned long)rx_ring->write_idx_mirror);
238	        }
239	
240	      usleep(1000);
241	    }
242	
243	  sf32lb58_bt_rx_ring_ready("sf32lb58 wait");
244	  return -ETIMEDOUT;
245	}
