277	static size_t sf32lb58_bt_ring_data_len(uint32_t rd_ptr, uint32_t wr_ptr,
278	                                        uint32_t buffer_size)
279	{
280	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
281	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
282	  uint32_t rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
283	  uint32_t wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
284	
285	  if (rd_idx == wr_idx)
286	    {
287	      return rd_mirror == wr_mirror ? 0 : buffer_size;
288	    }
289	
290	  if (wr_idx > rd_idx)
291	    {
292	      return wr_idx - rd_idx;
293	    }
294	
295	  return buffer_size - (rd_idx - wr_idx);
296	}
297	
298	static size_t sf32lb58_bt_ring_space_len(uint32_t rd_ptr, uint32_t wr_ptr,
299	                                         uint32_t buffer_size)
300	{
301	  return buffer_size - sf32lb58_bt_ring_data_len(rd_ptr, wr_ptr,
302	                                                  buffer_size);
303	}
304	
305	static uint32_t sf32lb58_bt_ring_advance(uint32_t ptr, size_t len,
306	                                         uint32_t buffer_size)
307	{
308	  uint32_t idx = CB_GET_PTR_IDX(ptr);
309	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
310	
311	  idx += len;
312	  if (idx >= buffer_size)
313	    {
314	      idx -= buffer_size;
315	      mirror = ~mirror;
316	    }
317	
318	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
319	}
320	
321	static size_t sf32lb58_bt_ring_copy(uint8_t *dst,
322	                                    const struct circular_buf *rx_ring,
323	                                    uint32_t rd_ptr,
324	                                    size_t len)
325	{
326	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
327	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
328	  size_t tail;
329	
330	  if (len == 0)
331	    {
332	      return 0;
333	    }
334	
335	  tail = rx_ring->buffer_size - rd_idx;
336	  if (tail >= len)
337	    {
338	      memcpy(dst, &pool[rd_idx], len);
339	      return len;
340	    }
341	
342	  memcpy(dst, &pool[rd_idx], tail);
343	  memcpy(&dst[tail], pool, len - tail);
344	  return len;
345	}
346	
347	static size_t sf32lb58_bt_ring_write(struct circular_buf *tx_ring,
348	                                     const uint8_t *src, size_t len)
349	{
350	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
351	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
352	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
353	  size_t space;
354	  size_t tail;
355	
356	  space = sf32lb58_bt_ring_space_len(tx_ring->read_idx_mirror,
357	                                     wr_ptr,
358	                                     tx_ring->buffer_size);
359	  if (space == 0)
360	    {
361	      return 0;
362	    }
363	
364	  if (len > space)
365	    {
366	      len = space;
367	    }
368	
369	  tail = tx_ring->buffer_size - wr_idx;
370	  if (tail >= len)
371	    {
372	      memcpy(&pool[wr_idx], src, len);
373	      up_clean_dcache((uintptr_t)&pool[wr_idx],
374	                      (uintptr_t)&pool[wr_idx] + len);
375	    }
376	  else
377	    {
378	      memcpy(&pool[wr_idx], src, tail);
379	      memcpy(pool, &src[tail], len - tail);
380	      up_clean_dcache((uintptr_t)&pool[wr_idx],
381	                      (uintptr_t)&pool[wr_idx] + tail);
382	      up_clean_dcache((uintptr_t)pool,
383	                      (uintptr_t)pool + len - tail);
384	    }
385	
386	  tx_ring->write_idx_mirror = sf32lb58_bt_ring_advance(wr_ptr, len,
387	                                                       tx_ring->buffer_size);
388	  up_clean_dcache((uintptr_t)tx_ring,
389	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
390	  __DSB();
391	
392	  return len;
393	}
394	
395	static size_t sf32lb58_bt_tx_pending(struct circular_buf *tx_ring,
396	                                     uint32_t *rd_ptr,
397	                                     uint32_t *wr_ptr)
398	{
399	  uint32_t rd;
400	  uint32_t wr;
401	
402	  up_invalidate_dcache((uintptr_t)SF32LB58_BT_TX_BUF_ADDR,
403	                       (uintptr_t)SF32LB58_BT_TX_BUF_ADDR +
404	                       sizeof(*tx_ring));
405	
406	  rd = tx_ring->read_idx_mirror;
407	  wr = tx_ring->write_idx_mirror;
408	
409	  if (rd_ptr != NULL)
410	    {
411	      *rd_ptr = rd;
412	    }
413	
414	  if (wr_ptr != NULL)
415	    {
416	      *wr_ptr = wr;
417	    }
418	
419	  return sf32lb58_bt_ring_data_len(rd, wr, tx_ring->buffer_size);
420	}
