428	static int sf32lb58_bt_wait_tx_idle(struct circular_buf *tx_ring)
429	{
430	  uint32_t start_time = HAL_GetTick();
431	  uint32_t tick_count = 0;
432	  uint32_t rd_ptr = 0;
433	  uint32_t wr_ptr = 0;
434	
435	  while (sf32lb58_bt_tx_pending(tx_ring, &rd_ptr, &wr_ptr) > 0)
436	    {
437	      sf32lb58_bt_trigger_tx();
438	
439	      if (HAL_GetTick() != start_time)
440	        {
441	          tick_count++;
442	          start_time = HAL_GetTick();
443	        }
444	
445	      if (tick_count >= 100)
446	        {
447	          syslog(LOG_ERR,
448	                 "sf32lb58 bt tx busy: rd=%08lx wr=%08lx\n",
449	                 (unsigned long)rd_ptr,
450	                 (unsigned long)wr_ptr);
451	          return -ETIMEDOUT;
452	        }
453	
454	      usleep(1000);
455	    }
456	
457	  return OK;
458	}
