460	static size_t sf32lb58_bt_tx_chunk_len(const uint8_t *data,
461	                                       size_t len,
462	                                       size_t offset)
463	{
464	  size_t remaining = len - offset;
465	
466	  if (offset == 0 && remaining > 1)
467	    {
468	      return 1;
469	    }
470	
471	  return remaining;
472	}
