474	static void sf32lb58_bt_rx_worker(FAR void *arg)
475	{
476	  struct sf32lb58_bt_env_s *env = arg;
477	
478	  for (;;)
479	    {
480	      irqstate_t flags;
481	      int empty_retries = 0;
482	
483	      for (;;)
484	        {
485	          size_t size;
486	          size_t read_len;
487	          int ret;
488	          struct circular_buf *rx_ring;
489	          uint32_t wr_ptr;
490	
491	          flags = enter_critical_section();
492	
493	          if (!env->queue_open ||
494	              env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
495	            {
496	              env->rx_work_pending = false;
497	              env->rx_worker_running = false;
498	              leave_critical_section(flags);
499	              return;
500	            }
501	
502	          leave_critical_section(flags);
503	
504	          up_invalidate_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
505	                               (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
506	                               SF32LB58_BT_RX_BUF_SIZE);
507	
508	          flags = enter_critical_section();
509	
510	          if (!env->queue_open ||
511	              env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
512	            {
513	              env->rx_work_pending = false;
514	              env->rx_worker_running = false;
515	              leave_critical_section(flags);
516	              return;
517	            }
518	
519	          rx_ring = (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
520	          wr_ptr = rx_ring->write_idx_mirror;
521	          size = sf32lb58_bt_ring_data_len(env->rx_read_idx_mirror,
522	                                          wr_ptr,
523	                                          rx_ring->buffer_size);
524	          if (size == 0)
525	            {
526	              leave_critical_section(flags);
527	
528	              if (empty_retries++ < 20)
529	                {
530	                  usleep(1000);
531	                  continue;
532	                }
533	
534	              break;
535	            }
536	
537	          empty_retries = 0;
538	
539	          if (size > sizeof(env->data_buf))
540	            {
541	              size = sizeof(env->data_buf);
542	            }
543	
544	          read_len = sf32lb58_bt_ring_copy(env->data_buf, rx_ring,
545	                                           env->rx_read_idx_mirror, size);
546	          if (read_len == 0)
547	            {
548	              leave_critical_section(flags);
549	              break;
550	            }
551	
552	          env->rx_read_idx_mirror = sf32lb58_bt_ring_advance(
553	              env->rx_read_idx_mirror, read_len, rx_ring->buffer_size);
554	          rx_ring->read_idx_mirror = env->rx_read_idx_mirror;
555	          __DSB();
556	
557	          up_clean_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
558	                          (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
559	                          sizeof(*rx_ring));
560	
561	          env->rx_count++;
562	
563	          leave_critical_section(flags);
564	
565	          if (env->notify_host == NULL)
566	            {
567	              continue;
568	            }
569	
570	          ret = env->notify_host(env->data_buf, read_len);
571	          if (ret < 0)
572	            {
573	              syslog(LOG_ERR, "sf32lb58 bt rx callback: %d\n", ret);
574	            }
575	        }
576	
577	      flags = enter_critical_section();
578	      if (!env->rx_work_pending)
579	        {
580	          env->rx_worker_running = false;
581	          leave_critical_section(flags);
582	          break;
583	        }
584	
585	      env->rx_work_pending = false;
586	      leave_critical_section(flags);
587	    }
588	}
