590	static int32_t sf32lb58_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
591	{
592	  struct sf32lb58_bt_env_s *env = &g_sf32lb58_bt_env;
593	  irqstate_t flags;
594	  bool queue_work;
595	
596	  if (handle != env->ipc_port)
597	    {
598	      return -EINVAL;
599	    }
600	
601	  if (!env->queue_open)
602	    {
603	      return OK;
604	    }
605	
606	  flags = enter_critical_section();
607	  env->rx_work_pending = true;
608	  queue_work = !env->rx_worker_running && work_available(&env->rx_work);
609	  if (queue_work)
610	    {
611	      env->rx_worker_running = true;
612	    }
613	  leave_critical_section(flags);
614	
615	  if (queue_work)
616	    {
617	      int ret;
618	
619	      ret = work_queue(HPWORK, &env->rx_work, sf32lb58_bt_rx_worker,
620	                       env, 0);
621	      if (ret < 0)
622	        {
623	          flags = enter_critical_section();
624	          env->rx_worker_running = false;
625	          leave_critical_section(flags);
626	
627	          syslog(LOG_ERR, "sf32lb58 bt queue rx work failed: %d\n", ret);
628	          return ret;
629	        }
630	    }
631	
632	  return OK;
633	}
