739	int sf32lb58_bt_controller_enable(void)
740	{
741	  int ret;
742	
743	  if (g_sf32lb58_bt_status == SF32LB58_BT_STATUS_ENABLED)
744	    {
745	      return OK;
746	    }
747	
748	  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_INITED)
749	    {
750	      return -EPERM;
751	    }
752	
753	  syslog(LOG_INFO, "sf32lb58 bt: preparing NVDS at 0x%08x size %d\n",
754	         (unsigned int)SF32LB58_BT_NVDS_BUF_START,
755	         (int)SF32LB58_BT_NVDS_BUF_SIZE);
756	  sf32lb58_bt_prepare_stack_nvds();
757	  HAL_LCPU_ASSERT_INFO_clear();
758	
759	  /* Wake the LCPU first so the LPSYS bus bridge is powered.
760	   * This must happen BEFORE lcpu_power_on() because the IPC mailbox
761	   * CxIER register is on the LPSYS APB bus and only writable when
762	   * the bus bridge is active.  lcpu_power_on() will reset+halt the
763	   * LCPU and reconfigure it, so this early wake is just for the bus
764	   * bridge power domain.
765	   */
766	
767	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
768	  g_sf32lb58_bt_env.wake_held = true;
769	
770	  syslog(LOG_INFO, "sf32lb58 bt: powering on LCPU\n");
771	  ret = lcpu_power_on();
772	  if (ret != 0)
773	    {
774	      syslog(LOG_ERR, "sf32lb58 bt: lcpu_power_on failed: %d\n", ret);
775	      return -EIO;
776	    }
777	
778	  syslog(LOG_INFO, "sf32lb58 bt: LCPU powered on, opening IPC\n");
779	
780	  /* lcpu_power_on() keeps the bus bridge active (no cancel inside).
781	   * Open the IPC queue while the bridge is powered, then cancel.
782	   */
783	
784	  g_sf32lb58_bt_env.wake_held = true;
785	
786	  syslog(LOG_INFO, "sf32lb58 bt: calling ipc_queue_open\n");
787	  ret = ipc_queue_open(g_sf32lb58_bt_env.ipc_port);
788	  syslog(LOG_INFO, "sf32lb58 bt: ipc_queue_open returned %d\n", ret);
789	
790	  /* Check if NVIC interrupt for mailbox is enabled */
791	  {
792	    uint32_t iser0 = NVIC->ISER[0];
793	    uint32_t iser1 = NVIC->ISER[1];
794	    syslog(LOG_INFO, "sf32lb58 bt: NVIC ISER0=%08lx ISER1=%08lx\n",
795	           (unsigned long)iser0, (unsigned long)iser1);
796	  }
797	  if (ret < 0)
798	    {
799	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
800	      g_sf32lb58_bt_env.wake_held = false;
801	      return ret;
802	    }
803	
804	  syslog(LOG_INFO, "sf32lb58 bt: flushing TX ring, then waiting RX ring\n");
805	  up_clean_dcache((uintptr_t)SF32LB58_BT_TX_BUF_ADDR,
806	                  (uintptr_t)SF32LB58_BT_TX_BUF_ADDR +
807	                  SF32LB58_BT_TX_BUF_SIZE);
808	  __DSB();
809	
810	  {
811	    struct circular_buf *rx_ring =
812	        (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
813	
814	    ret = sf32lb58_bt_wait_rx_ring_ready();
815	    if (ret < 0)
816	      {
817	        syslog(LOG_ERR, "sf32lb58 rx ring not ready: %d\n", ret);
818	        ipc_queue_close(g_sf32lb58_bt_env.ipc_port);
819	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
820	        g_sf32lb58_bt_env.wake_held = false;
821	        return ret;
822	      }
823	
824	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
825	    g_sf32lb58_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
826	
827	    up_clean_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
828	                    (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
829	                    sizeof(*rx_ring));
830	    __DSB();
831	  }
832	
833	  g_sf32lb58_bt_env.queue_open = true;
834	  g_sf32lb58_bt_status = SF32LB58_BT_STATUS_ENABLED;
835	
836	  return OK;
837	}
838	
839	int sf32lb58_bt_controller_disable(void)
840	{
841	  int ret = OK;
842	  int tmpret;
843	  bool queue_open;
844	
845	  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_ENABLED)
846	    {
847	      return -EPERM;
848	    }
849	
850	  queue_open = g_sf32lb58_bt_env.queue_open;
851	  g_sf32lb58_bt_env.queue_open = false;
852	  g_sf32lb58_bt_env.rx_work_pending = false;
853	  g_sf32lb58_bt_env.rx_worker_running = false;
854	  if (!work_available(&g_sf32lb58_bt_env.rx_work))
855	    {
856	      tmpret = work_cancel_sync(HPWORK, &g_sf32lb58_bt_env.rx_work);
857	      if (tmpret < 0 && tmpret != -ENOENT && ret == OK)
858	        {
859	          ret = tmpret;
860	        }
861	    }
862	
863	  if (queue_open)
864	    {
865	      tmpret = ipc_queue_close(g_sf32lb58_bt_env.ipc_port);
866	      if (tmpret < 0 && ret == OK)
867	        {
868	          ret = tmpret;
869	        }
870	    }
871	
872	  if (g_sf32lb58_bt_env.wake_held)
873	    {
874	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
875	      g_sf32lb58_bt_env.wake_held = false;
876	    }
877	
878	  tmpret = lcpu_power_off();
879	  if (tmpret != 0 && ret == OK)
880	    {
881	      ret = -EIO;
882	    }
883	
884	  g_sf32lb58_bt_env.notify_host = NULL;
885	  g_sf32lb58_bt_status = SF32LB58_BT_STATUS_INITED;
886	  return ret;
887	}
888	
889	int sf32lb58_host_send_packet(const uint8_t *data, uint16_t len)
890	{
891	  struct circular_buf *tx_ring =
892	      (struct circular_buf *)SF32LB58_BT_TX_BUF_ADDR;
893	  uint32_t start_time;
894	  uint32_t tick_count;
895	  size_t written;
896	  size_t remaining;
897	  size_t offset;
898	  size_t chunk;
899	  size_t chunks;
900	  uint32_t wr_ptr;
901	  int ret;
902	
903	  if (data == NULL || len == 0)
904	    {
905	      return -EINVAL;
906	    }
907	
908	  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_ENABLED ||
909	      !g_sf32lb58_bt_env.queue_open)
910	    {
911	      syslog(LOG_ERR, "sf32lb58 send: not ready status=%d open=%d\n",
912	             g_sf32lb58_bt_status, g_sf32lb58_bt_env.queue_open);
913	      return -ENODEV;
914	    }
915	
916	  syslog(LOG_INFO, "sf32lb58 send: len=%d type=%02x\n",
917	         len, data[0]);
918	
919	  offset = 0;
920	  remaining = len;
921	  start_time = HAL_GetTick();
922	  tick_count = 0;
923	  chunks = 0;
924	  wr_ptr = 0;
925	
926	  ret = sf32lb58_bt_wait_tx_idle(tx_ring);
927	  if (ret < 0)
928	    {
929	      return ret;
930	    }
931	
932	  while (remaining > 0)
933	    {
934	      irqstate_t flags;
935	
936	      chunk = sf32lb58_bt_tx_chunk_len(data, len, offset);
937	
938	      up_invalidate_dcache((uintptr_t)SF32LB58_BT_TX_BUF_ADDR,
939	                           (uintptr_t)SF32LB58_BT_TX_BUF_ADDR +
940	                           sizeof(*tx_ring));
941	
942	      flags = enter_critical_section();
943	      written = sf32lb58_bt_ring_write(tx_ring, data + offset, chunk);
944	      leave_critical_section(flags);
945	
946	      if (written == 0)
947	        {
948	          if (HAL_GetTick() != start_time)
949	            {
950	              tick_count++;
951	              start_time = HAL_GetTick();
952	            }
953	
954	          if (tick_count >= 10)
955	            {
956	              syslog(LOG_ERR,
957	                     "sf32lb58 bt tx timeout: remaining=%lu\n",
958	                     (unsigned long)remaining);
959	              return -ETIMEDOUT;
960	            }
961	
962	          continue;
963	        }
964	
965	      offset += written;
966	      remaining -= written;
967	
968	      __DSB();
969	      wr_ptr = tx_ring->write_idx_mirror;
970	      sf32lb58_bt_trigger_tx();
971	      chunks++;
972	    }
973	
974	  if (data[0] == SF32LB58_BT_H4_CMD)
975	    {
976	      up_invalidate_dcache((uintptr_t)SF32LB58_BT_TX_BUF_ADDR,
977	                           (uintptr_t)SF32LB58_BT_TX_BUF_ADDR +
978	                           sizeof(*tx_ring));
979	      syslog(LOG_INFO,
980	             "sf32lb58 send: after trigger rd=%08lx wr=%08lx\n",
981	             (unsigned long)tx_ring->read_idx_mirror,
982	             (unsigned long)tx_ring->write_idx_mirror);
983	
984	      ret = sf32lb58_bt_wait_tx_idle(tx_ring);
985	      if (ret < 0)
986	        {
987	          syslog(LOG_ERR, "sf32lb58 send: wait_tx_idle failed: %d\n", ret);
988	          return ret;
989	        }
990	    }
991	
992	  return OK;
993	}
