int sf32lb58_bt_initialize(void)
{
  int ret;

  ret = uart_bth4_register("/dev/ttyHCI0", &g_sf32lb58_bt_priv.drv);
  if (ret < 0 && ret != -EEXIST)
    {
      wlerr("Failed to register /dev/ttyHCI0: %d\n", ret);
      return ret;
    }

  /* Do NOT call z_sys_init() here.  The bluetoothd framework calls
   * bt_sal_init() → z_sys_init() during its startup.  Calling it
   * twice causes the second call to block or fail.
   */

  return OK;
}

